 const verificationLimit=rateLimit({windowMs:15*60000,max:180,standardHeaders:'draft-7',legacyHeaders:false,message:{error:'Попробуйте позже.',code:'FIREBASE_RATE_LIMIT'}});
 app.post('/api/firebase/verification-status',verificationLimit,firebaseRequired,asyncRoute(async(req,res)=>{
  res.set('Cache-Control','no-store');if(!req.cookies.pongy_verification)return res.json({pending:false});
  let claim;try{claim=jwt.verify(req.cookies.pongy_verification,config.jwtSecret,{algorithms:['HS256'],issuer:'pongy-server',audience:'pongy-verification'});if(typeof claim.uid!=='string'||typeof claim.email!=='string'||typeof claim.fr!=='string'||typeof claim.pid!=='string')throw new Error();}catch{clearPending(res);return res.json({pending:false});}
  if(!db.prepare('SELECT id FROM pending_verifications WHERE id=? AND uid=? AND expires_at>?').get(claim.pid,claim.uid,Date.now())){clearPending(res);return res.json({pending:false});}
  let session;try{session=await firebase.pendingSession(firebase.open(claim.fr,claim.uid),claim.uid,claim.email);}catch(error){if(error.status===401)clearPending(res);throw error;}
  if(session.user.emailVerified!==true){setPending(res,session,claim.exp,claim.pid);return res.json({pending:true});}
  return completeFirebaseLogin(res,session,claim.pid);
 }));
 app.post('/api/firebase/resend-verification',authLimit,mailLimit,firebaseRequired,asyncRoute(async(req,res)=>{const email=emailValue(req.body?.email),password=req.body?.password;if(!email||typeof password!=='string'||Buffer.byteLength(password)>72)return res.status(400).json({error:'Укажите почту и пароль для повторной отправки.'});if(!sendCooldown(email))return res.status(429).json({error:'Подождите минуту перед повторной отправкой.'});const result=await firebase.resend(email,password,req.body.locale);if(result.session)setPending(res,result.session);res.json(result.alreadyVerified?{alreadyVerified:true}:{verificationRequired:true});}));
