 async function getRecord(req,kind,id,includeContent=true){if(store.enabled)return store.get(req.user.firebase_uid,req.firebaseIdToken,kind,id,{content:includeContent});const row=kind==='chats'?db.prepare('SELECT * FROM chats WHERE id=? AND user_id=?').get(id,req.user.id):db.prepare('SELECT json FROM '+(kind==='files'?'files':'preferences')+' WHERE '+(kind==='files'?'id=? AND user_id=?':'user_id=?')).get(...(kind==='files'?[id,req.user.id]:[req.user.id]));return row?(kind==='chats'?{...row,messages:JSON.parse(row.messages),pinned:!!row.pinned}:JSON.parse(row.json)):null;}
 async function listChats(req){return store.enabled?store.list(req.user.firebase_uid,req.firebaseIdToken,'chats'):db.prepare('SELECT id,title,messages,updated_at,pinned FROM chats WHERE user_id=? ORDER BY pinned DESC,updated_at DESC LIMIT 500').all(req.user.id).map(r=>({...r,messages:JSON.parse(r.messages),pinned:!!r.pinned}));}
